package vn.hust.restaurant.view;
import java.awt.*;import java.util.*;import javax.swing.*;import javax.swing.table.*;import vn.hust.restaurant.config.AppContext;import vn.hust.restaurant.model.Customer;
public class CustomerPanel extends JPanel implements Refreshable{private final AppContext ctx;private final JTextField search=new JTextField(20);private final DefaultTableModel model=Ui.model("ID","Mã","Họ tên","SĐT","Email","Điểm","Trạng thái");private final JTable table=new JTable(model);private java.util.List<Customer>data=java.util.List.of();public CustomerPanel(AppContext c){ctx=c;setLayout(new BorderLayout());JButton add=new JButton("Thêm"),edit=new JButton("Sửa"),del=new JButton("Ngừng hoạt động"),reload=new JButton("Tìm/Làm mới");add(Ui.toolbar(new JLabel("Tên/SĐT:"),search,reload,add,edit,del),BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);reload.addActionListener(e->refresh());search.addActionListener(e->refresh());add.addActionListener(e->edit(null));edit.addActionListener(e->{int r=table.getSelectedRow();if(r>=0)edit(data.get(r));});del.addActionListener(e->{int r=table.getSelectedRow();if(r>=0&&Ui.confirm(this,"Ngừng hoạt động khách hàng?"))Ui.run(this,()->{ctx.customers.deactivate(data.get(r).id());refresh();});});refresh();}
 public void refresh(){Ui.run(this,()->{data=ctx.customers.list(search.getText());model.setRowCount(0);for(Customer x:data)model.addRow(new Object[]{x.id(),x.code(),x.fullName(),x.phone(),x.email(),x.points(),x.status()});});}
 private void edit(Customer x){JTextField code=Ui.field(x==null?"KH"+(System.currentTimeMillis()%100000):x.code(),15),name=Ui.field(x==null?"":x.fullName(),20),phone=Ui.field(x==null?"":x.phone(),15),email=Ui.field(x==null?"":x.email(),20),points=Ui.field(x==null?"0":String.valueOf(x.points()),8);Object[]f={"Mã",code,"Họ tên",name,"SĐT",phone,"Email",email,"Điểm",points};if(JOptionPane.showConfirmDialog(this,f,x==null?"Thêm khách hàng":"Sửa khách hàng",JOptionPane.OK_CANCEL_OPTION)==JOptionPane.OK_OPTION)Ui.run(this,()->{ctx.customers.save(new Customer(x==null?0:x.id(),code.getText(),name.getText(),phone.getText(),email.getText(),Ui.integer(points.getText()),x==null?"HOAT_DONG":x.status()));refresh();});}}
